LLVM replaces pointer with null without respecting provenance

Based on an observation by @scottmcm on [zulip](https://rust-lang.zulipchat.com/#narrow/channel/136281-t-opsem/topic/Provenance.20and.20null.20pointers/near/628046395).

https://rust.godbolt.org/z/z6Evsrdob
```rust
pub fn wat(p: *const u8) -> *const u8 {
    assert!(p.is_null());
    p // optimized to `ptr null`, without provenance
}

pub fn off_and_back(p: *const u8, n: usize) -> *const u8 {
    let q = p.wrapping_add(n); // q = p + n
    assert!(q.is_null(), "{q:?} is not null");
    wat(q).wrapping_sub(n) // q - n = p
}

pub fn broken(x: &u8) -> u8 {
    // SAFETY: `off_and_back` returns `x`, which is valid for reads
    unsafe {
        // LLVM sees UB here because the pointer has nullary provenance, 
        // so it concludes that one of the assertions must have failed
        off_and_back(x, std::ptr::from_ref(x).addr().wrapping_neg())
            .read()
    }
}


pub fn main() {
    // panics on "0x0 is not null", which is impossible
    broken(std::hint::black_box(&1));
}
```

