use std::num::NonZeroU32;

#[inline(never)]
fn is_zero(a: &u32) -> bool {
    unsafe {
        let a: &NonZeroU32 = std::mem::transmute(a);
        let z: &NonZeroU32 = std::mem::transmute(&0u32);
        std::intrinsics::raw_eq(a, z)
